#include <iostream>
using namespace std;

long long power(long long a, int b) {
    long long r = 1;
    while (b--) r *= a;
    return r;
}

int main() {
    int N, i;
    cin >> N >> i;
    if (N == 1) {
        cout << 1 << endl;
        return 0;
    }
    long long denom = power(N - 1, N - 1);
    long long m = (i + 1 + denom - 1) / denom;
    long long ans = m * power(N, N) - 1LL * (N - 1) * i;
    cout << ans << endl;
    return 0;
}
